function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function req(url,opts={}){const r=await fetch(url,{credentials:'same-origin',...opts});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Ошибка запроса');return d}
function mergeLoaded(saved){data=clone(defaults);if(saved&&saved.fields)data.fields={...data.fields,...saved.fields};data.hidden=Array.isArray(saved?.hidden)?saved.hidden:[];if(saved&&saved.configured){['products','steps','photos','videos','checks','clients','audience'].forEach(k=>{if(Array.isArray(saved[k]))data[k]=saved[k]})}data.checks=data.checks.map(x=>typeof x==='string'?{title:x}:x)}
function login(){ $('#login').classList.add('hidden');$('#editor').classList.remove('hidden');load()}
async function load(){try{const d=await req('/api/content.php');mergeLoaded(d.content);draw()}catch(e){$('#msg').textContent=e.message}}
function draw(){ $('#tabs').innerHTML=sections.map(([id,name])=>'<button type="button" data-tab="'+id+'" class="'+(tab===id?'active':'')+'">'+name+'</button>').join('');$('#sectionTitle').textContent=sections.find(x=>x[0]===tab)[1];let html='<label class="field"><span><input type="checkbox" id="hideSection" '+(data.hidden.includes(tab)?'checked':'')+'> Скрыть этот раздел на главной странице</span></label>';
(fields[tab]||[]).forEach(([key,label])=>{const val=data.fields[key]??'';html+='<label class="field">'+label+(String(val).length>90?'<textarea data-field="'+key+'">'+esc(val)+'</textarea>':'<input data-field="'+key+'" value="'+esc(val)+'">')+'</label>'});
if(lists[tab]){const key=lists[tab].key;html+='<h3>'+lists[tab].title+'</h3><p class="hint">Добавляйте новые записи, меняйте их поля или удаляйте ненужные.</p>'+data[key].map((x,i)=>entry(key,x,i)).join('')+'<button type="button" id="addEntry">＋ Добавить</button>'}
if(tab==='gallery'&&!data.photos.length)html+='<p class="hint">Галерея пока использует фотографии, встроенные в текущую версию сайта. Добавленные здесь фото появятся отдельными карточками; старые можно будет редактировать после переноса в редактор.</p>';
$('#workspace').innerHTML=html}
function entry(key,x,i){const inputs=(obj)=>Object.entries(obj).filter(([k])=>k!=='id').map(([k,v])=>'<label class="field">'+({group:'Категория услуги',title:'Название',text:'Описание',price:'Цена / подпись',image:'Имя или адрес изображения',number:'Номер этапа',url:'Ссылка на видео',icon:'Значок',category:'Категория фото',caption:'Подпись фото',name:'Название организации'}[k]||k)+'<input data-item="'+i+'" data-list="'+key+'" data-key="'+k+'" value="'+esc(v)+'"></label>').join('');
return '<div class="entry"><div class="entry-head"><b>Запись '+(i+1)+'</b><button type="button" class="danger" data-remove="'+key+'" data-index="'+i+'">Удалить</button></div>'+(x.url&&x.url.includes('youtube')?'<div class="hint">Видео: '+esc(x.url)+'</div>':'')+'<div class="grid">'+inputs(x)+'</div>'+(key==='photos'&&x.image?'<img class="preview" src="'+esc(x.image.startsWith('/')?x.image:'/images/'+x.image)+'" alt="">':'')+'</div>'}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;collect();tab=b.dataset.tab;draw()});
function collect(){const hide=$('#hideSection');if(hide){data.hidden=data.hidden.filter(x=>x!==tab);if(hide.checked)data.hidden.push(tab)}document.querySelectorAll('[data-field]').forEach(n=>data.fields[n.dataset.field]=n.value);document.querySelectorAll('[data-item]').forEach(n=>{const x=data[n.dataset.list][Number(n.dataset.item)];x[n.dataset.key]=n.value})}
$('#workspace').addEventListener('click',e=>{if(e.target.id==='addEntry'){collect();const k=lists[tab].key;const seed={products:{group:'metal',title:'Новая услуга',text:'Описание услуги',price:'Цена по запросу',image:''},steps:{number:String(data.steps.length+1).padStart(2,'0'),title:'Новый этап',text:''},photos:{image:'',category:'Металлоконструкции',title:'Новая фотография',caption:''},videos:{title:'Новое видео',url:''},checks:{title:'Новый пункт'},clients:{name:'Новый клиент'},audience:{icon:'⌂',title:'Новая аудитория',text:''}}[k];data[k].push(clone(seed));draw()}const r=e.target.closest('[data-remove]');if(r){collect();data[r.dataset.remove].splice(Number(r.dataset.index),1);draw()}});
$('#save').onclick=async()=>{collect();$('#msg').textContent='Сохраняю…';try{const fd=new FormData();fd.append('action','save');fd.append('csrf',csrf);fd.append('content',JSON.stringify(data));await req('/api/content.php',{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});$('#msg').textContent='Сохранено. Изменения опубликованы на главной странице.'}catch(e){$('#msg').textContent=e.message}};
$('#reload').onclick=load;
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=await req('/admin/api.php?action=login',{method:'POST',body:new FormData(e.currentTarget)});csrf=d.csrf;login()}catch(x){$('#loginMsg').textContent=x.message}});
$('#upload').onclick=async()=>{const f=$('#file').files[0];if(!f){$('#uploadMsg').textContent='Сначала выберите файл.';return}const fd=new FormData();fd.append('action','upload');fd.append('csrf',csrf);fd.append('file',f);try{const d=await req('/api/content.php',{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});$('#uploadMsg').textContent='Файл загружен: '+d.url+' — скопируйте адрес в поле изображения или видео.';if(tab==='gallery'&&d.type==='image'){collect();data.photos.push({image:d.url,category:'Новая категория',title:'Новое фото',caption:''});draw()}if(tab==='videos'&&d.type==='video'){collect();data.videos.push({title:f.name,url:d.url});draw()}}catch(e){$('#uploadMsg').textContent=e.message}};
(async()=>{try{const d=await req('/admin/api.php?action=status');if(d.authenticated){csrf=d.csrf;login()}}catch(e){}})();
</script></body></html>